#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    friend class Vet;
};

class Vet {
public:
    void checkup(const Cat& c) {
        cout << "猫大夫打开 " << c.name << " 的盒子：" << c.fish << " 条，吃得不错喵" << endl;
    }
};

int main() {
    int fish = 0;
    cin >> fish;

    Cat c1("{name}", fish);
    Vet v;
    v.checkup(c1);
    return 0;
}
